"""Publish a uProtocol powertrain event using the existing mosquitto_pub tool."""
import argparse
import os
import shlex
import subprocess
import time
import uuid
import json


def publish_command(host, port, mode, authority="powertrain", entity=0xBC, version=1, resource=0x8001):
    """Encode the pinned MQTT mapping; JSON remains the application payload."""
    if not authority or any(c not in "abcdefghijklmnopqrstuvwxyz0123456789-._~" for c in authority):
        raise ValueError("authority must be a lowercase URI name")
    if not 0 <= entity <= 0xFFFFFFFF or (entity & 0xFFFF) == 0xFFFF or entity >> 16 == 0xFFFF:
        raise ValueError("entity must be a concrete 32-bit uEntity ID")
    if not 0 <= version < 255 or not 0x8000 <= resource < 0xFFFF:
        raise ValueError("version/resource must identify a concrete publish resource")
    milliseconds = time.time_ns() // 1_000_000
    identifier = bytearray(milliseconds.to_bytes(6, "big") + os.urandom(10))
    identifier[6] = (identifier[6] & 0x0F) | 0x70
    identifier[8] = (identifier[8] & 0x3F) | 0x80
    source = f"up://{authority}/{entity:X}/{version:X}/{resource:X}"
    topic = f"{authority}/{entity & 0xFFFF:X}/{entity >> 16:X}/{version:X}/{resource:X}"
    command = ["mosquitto_pub", "-V", "mqttv5", "-h", host, "-p", str(port),
               "-q", "1", "-t", topic, "-m", json.dumps({"Mode": mode})]
    for key, value in [("uP", "1"), ("1", str(uuid.UUID(bytes=bytes(identifier)))),
                       ("2", "up-pub.v1"), ("3", source), ("5", "CS1")]:
        command.extend(["-D", "PUBLISH", "user-property", key, value])
    command.extend(["-D", "PUBLISH", "content-type", "3",
                    "-D", "PUBLISH", "message-expiry-interval", "10"])
    return command


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--host", required=True)
    parser.add_argument("--port", type=int, default=1883)
    parser.add_argument("--mode", required=True, help="Value displayed as the JSON Mode string")
    parser.add_argument("--authority", default="powertrain")
    parser.add_argument("--entity", type=lambda value: int(value, 16), default=0xBC)
    parser.add_argument("--version", type=lambda value: int(value, 16), default=1)
    parser.add_argument("--resource", type=lambda value: int(value, 16), default=0x8001)
    parser.add_argument("--dry-run", action="store_true", help="Print the command without publishing")
    args = parser.parse_args()
    if not 1 <= args.port <= 65535:
        parser.error("port must be between 1 and 65535")
    try:
        command = publish_command(args.host, args.port, args.mode, args.authority,
                                  args.entity, args.version, args.resource)
    except ValueError as error:
        parser.error(str(error))
    if args.dry_run:
        print(shlex.join(command))
        return 0
    return subprocess.run(command, check=False).returncode


if __name__ == "__main__":
    raise SystemExit(main())
